import{_ as r,o as a,c as t,a5 as n}from"./chunks/framework.a5no_H3L.js";const g=JSON.parse('{"title":"进程与线程","description":"逆向分析的对象，是运行中的进程。这一章讲 Windows 里最基础的两个概念——进程和线程，它们是理解「程序如何运行、调试器在调试什么」的前提。","frontmatter":{"type":"explanation","level":"basic"},"headers":[],"relativePath":"reverse-engineering/03-windows-internals/chapter-01-process-thread.md","filePath":"reverse-engineering/03-windows-internals/chapter-01-process-thread.md"}'),s={name:"reverse-engineering/03-windows-internals/chapter-01-process-thread.md"};function i(d,e,l,c,o,h){return a(),t("div",null,[...e[0]||(e[0]=[n('<h1 id="进程与线程" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">进程与线程 <a class="header-anchor" href="#进程与线程" aria-label="Permalink to &quot;进程与线程&quot;">​</a></h1><p data-src-line="4" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">逆向分析的对象，是运行中的进程。这一章讲 Windows 里最基础的两个概念——进程和线程，它们是理解「程序如何运行、调试器在调试什么」的前提。</p><h2 id="_1-进程-资源的容器" tabindex="-1" data-src-line="6" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">1. 进程：资源的容器 <a class="header-anchor" href="#_1-进程-资源的容器" aria-label="Permalink to &quot;1. 进程：资源的容器&quot;">​</a></h2><p data-src-line="8" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">进程（process）是操作系统资源分配的基本单位。一个进程拥有：</p><ul data-src-line="10" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md"><li data-src-line="10" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">一个独立的虚拟地址空间（上一章讲过）。</li><li data-src-line="11" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">已加载的模块（<code>.exe</code> 和依赖的 <code>.dll</code>）。</li><li data-src-line="12" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">堆、栈、句柄表等资源。</li><li data-src-line="13" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">至少一个线程。</li></ul><p data-src-line="15" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">进程之间相互隔离：一个进程不能直接读写另一个进程的内存。调试器之所以能「看」目标进程的内存，是因为它通过操作系统的调试接口获得了特殊权限，而不是突破了隔离。</p><h2 id="_2-线程-执行的单位" tabindex="-1" data-src-line="17" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">2. 线程：执行的单位 <a class="header-anchor" href="#_2-线程-执行的单位" aria-label="Permalink to &quot;2. 线程：执行的单位&quot;">​</a></h2><p data-src-line="19" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">线程（thread）是 CPU 调度的基本单位，是真正「执行代码」的东西。一个进程可以有多个线程，它们共享进程的地址空间和资源，但各自有独立的：</p><ul data-src-line="21" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md"><li data-src-line="21" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">栈（每个线程一个栈）。</li><li data-src-line="22" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">寄存器上下文（一组寄存器值）。</li><li data-src-line="23" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">异常处理链。</li></ul><p data-src-line="25" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">CPU 在多个线程之间切换执行，每次切换都要保存/恢复寄存器上下文。这个「切换」就是上下文切换（context switch）。</p><h2 id="_3-逆向中如何看进程和线程" tabindex="-1" data-src-line="27" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">3. 逆向中如何看进程和线程 <a class="header-anchor" href="#_3-逆向中如何看进程和线程" aria-label="Permalink to &quot;3. 逆向中如何看进程和线程&quot;">​</a></h2><p data-src-line="29" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">调试器里，这些概念有直接的对应：</p><table tabindex="0"><thead data-src-line="31" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md"><tr data-src-line="31" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md"><th style="text-align:left;">概念</th><th style="text-align:left;">调试器里的对应</th></tr></thead><tbody data-src-line="33" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md"><tr data-src-line="33" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md"><td style="text-align:left;">进程</td><td style="text-align:left;">你正在调试的整个目标</td></tr><tr data-src-line="34" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md"><td style="text-align:left;">线程</td><td style="text-align:left;">调试器里可以切换的各个线程</td></tr><tr data-src-line="35" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md"><td style="text-align:left;">寄存器上下文</td><td style="text-align:left;">切换线程后看到的寄存器面板</td></tr><tr data-src-line="36" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md"><td style="text-align:left;">每个线程的栈</td><td style="text-align:left;">栈面板显示当前线程的栈</td></tr></tbody></table><p data-src-line="38" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">理解这些对应关系，能解释几个常见现象：</p><ul data-src-line="40" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md"><li data-src-line="40" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md"><strong>断点是进程级的还是线程级的</strong>：软件断点（<code>INT 3</code>）命中时，哪个线程执行到那里，哪个线程停下；其他线程可能还在跑。</li><li data-src-line="41" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md"><strong>调用栈属于线程</strong>：栈面板显示的调用链，是「当前线程」的调用链，不是整个进程的。</li><li data-src-line="42" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md"><strong>多线程程序的断点命中顺序不确定</strong>：哪个线程先执行到断点，取决于调度，所以多线程程序的调试现象可能每次不同。</li></ul><h2 id="_4-线程上下文-调试器「暂停」的本质" tabindex="-1" data-src-line="44" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">4. 线程上下文：调试器「暂停」的本质 <a class="header-anchor" href="#_4-线程上下文-调试器「暂停」的本质" aria-label="Permalink to &quot;4. 线程上下文：调试器「暂停」的本质&quot;">​</a></h2><p data-src-line="46" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">调试器让程序「停在某一行」，本质是：</p><ol data-src-line="48" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md"><li data-src-line="48" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">通过调试事件让目标进程的某个线程停下。</li><li data-src-line="49" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">读取该线程的上下文（<code>GetThreadContext</code>），得到它此刻的寄存器值、指令指针（RIP）。</li><li data-src-line="50" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">调试器把 RIP 指向的地址显示成「当前停在的位置」。</li></ol><p data-src-line="52" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">所以你在调试器里看到的「程序状态」，本质是「某个线程在某个瞬间的寄存器快照」。理解了这一点，就理解了动态调试的核心——它观察的是线程的执行快照。</p><hr><blockquote data-src-line="56" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md"><p data-src-line="56" data-src-file="reverse-engineering/03-windows-internals/chapter-01-process-thread.md">本章建立的是进程与线程的基本图景：进程是资源容器，线程是执行单位，调试器观察的是线程的执行快照。下一章看程序如何调用系统功能——<a href="./chapter-03-dll-api.html">DLL 加载与 Windows API</a>。</p></blockquote>',21)])])}const w=r(s,[["render",i]]);export{g as __pageData,w as default};
